package main

import (
	"encoding/json"
	"io"
	"net/http"
	"os"
)

func main() {
	port := os.Getenv("PORT")
	if port == "" {
		port = "3001"
	}

	http.HandleFunc("/aggregate", func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Content-Type", "application/json")
		resp, err := http.Get("http://localhost:3002/data")
		if err != nil {
			w.WriteHeader(http.StatusBadGateway)
			json.NewEncoder(w).Encode(map[string]string{"error": "Bad Gateway", "details": err.Error()})
			return
		}
		defer resp.Body.Close()
		body, _ := io.ReadAll(resp.Body)
		var dataB interface{}
		json.Unmarshal(body, &dataB)
		json.NewEncoder(w).Encode(map[string]interface{}{
			"service":   "A",
			"message":   "Hello from A",
			"dataFromB": dataB,
		})
	})

	http.ListenAndServe(":"+port, nil)
}

